#!/usr/bin/env python3
"""Arena Studio APK startup test (generated by arena_exe_builder).

Installs an APK on a connected phone or emulator through adb, launches it, watches whether it keeps running,
and saves the logcat, a screenshot and the game's own crash log.
Exit code: 0 = the app kept running, 1 = the app crashed, 2 = the test could not run.
Usage: python arena_apk_test.py game.apk [--seconds 30] [--out folder] [--serial ID] [--package NAME]
"""
import argparse
import os
import re
import shutil
import subprocess
import sys
import time

try:
    sys.stdout.reconfigure(errors="replace")
except Exception:
    pass

NO_WINDOW = getattr(subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0
CRASH_FILES = ("files/arena_android_crash.log", "files/app/startup_crash_log.txt")
EXTRA_FILES = ("files/app/startup_fatal_log.txt",)
PREFIX_LINE = re.compile(r"^\d\d-\d\d\s+[\d:.]+\s+[A-Z]/.*?\(\s*\d+\):\s?")


def find_adb(explicit=None):
    candidates = [explicit, shutil.which("adb")]
    for name in ("ANDROID_HOME", "ANDROID_SDK_ROOT"):
        root = os.environ.get(name)
        if root:
            candidates += [os.path.join(root, "platform-tools", "adb"), os.path.join(root, "platform-tools", "adb.exe")]
    local = os.environ.get("LOCALAPPDATA")
    if local:
        candidates.append(os.path.join(local, "Android", "Sdk", "platform-tools", "adb.exe"))
    home = os.path.expanduser("~")
    candidates += [os.path.join(home, "Android", "Sdk", "platform-tools", "adb"),
                   os.path.join(home, "Library", "Android", "sdk", "platform-tools", "adb")]
    for item in candidates:
        if item and os.path.isfile(item):
            return item
    return None


class Adb:
    def __init__(self, path):
        self.path = path
        self.serial = None

    def run(self, *args, timeout=60, binary=False):
        command = [self.path] + (["-s", self.serial] if self.serial else []) + [str(a) for a in args]
        try:
            proc = subprocess.run(command, stdout=subprocess.PIPE,
                                  stderr=subprocess.DEVNULL if binary else subprocess.STDOUT,
                                  timeout=timeout, creationflags=NO_WINDOW)
        except subprocess.TimeoutExpired:
            return 124, (b"" if binary else "adb timed out")
        except OSError as exc:
            return 127, (b"" if binary else str(exc))
        out = proc.stdout if binary else proc.stdout.decode("utf-8", "replace").replace("\r", "")
        return proc.returncode, out

    def shell(self, *args, timeout=60):
        return self.run("shell", *args, timeout=timeout)[1].strip()

    def devices(self):
        found = []
        for line in self.run("devices", timeout=30)[1].splitlines():
            parts = line.split()
            if len(parts) >= 2 and parts[1] == "device":
                found.append(parts[0])
        return found

    def packages(self):
        text = self.shell("pm", "list", "packages", "-3")
        return {line.strip()[8:] for line in text.splitlines() if line.strip().startswith("package:")}


def strip_prefix(line):
    return PREFIX_LINE.sub("", line)


def main():
    parser = argparse.ArgumentParser(description="Install an APK, launch it and report whether it crashes.")
    parser.add_argument("apk")
    parser.add_argument("--adb", help="path to adb (found automatically when omitted)")
    parser.add_argument("--serial", help="device id when several are connected")
    parser.add_argument("--seconds", type=int, default=30, help="how long the app must keep running")
    parser.add_argument("--out", default="apk_test_out")
    parser.add_argument("--package", help="app package id (found automatically when omitted)")
    parser.add_argument("--prefix", default="org.arenastudio", help="package prefix used to find the app")
    args = parser.parse_args()
    out = args.out
    os.makedirs(out, exist_ok=True)
    report = []

    def say(text):
        print(text, flush=True)
        report.append(text)

    def finish(verdict, code):
        with open(os.path.join(out, "RESULT.txt"), "w", encoding="utf-8") as handle:
            handle.write(verdict + "\n" + "\n".join(report) + "\n")
        return code

    if not os.path.isfile(args.apk):
        say("ERROR: APK not found: " + args.apk)
        return finish("ERROR", 2)
    path = find_adb(args.adb)
    if not path:
        say("ERROR: adb (Android platform-tools) was not found on this computer.\n"
            "Install it from https://developer.android.com/tools/releases/platform-tools, or use the GitHub virtual-phone test.")
        return finish("ERROR", 2)
    adb = Adb(path)
    adb.run("start-server", timeout=60)
    devices = []
    for _ in range(30):
        devices = [args.serial] if args.serial and args.serial in adb.devices() else ([] if args.serial else adb.devices())
        if devices:
            break
        time.sleep(2)
    if not devices:
        say("ERROR: no phone or emulator is connected.\n"
            "Plug the phone in with USB debugging turned on and accept the prompt on its screen, or start an emulator,\n"
            "or use the GitHub virtual-phone test instead.")
        return finish("ERROR", 2)
    adb.serial = devices[0]
    if len(devices) > 1:
        say("Several devices found; using " + adb.serial + " (use --serial to pick another).")
    for _ in range(60):
        if adb.shell("getprop", "sys.boot_completed").strip() == "1":
            break
        time.sleep(2)
    say("Device: %s, Android %s (API %s), ABIs: %s" % (
        adb.shell("getprop", "ro.product.model") or adb.serial, adb.shell("getprop", "ro.build.version.release"),
        adb.shell("getprop", "ro.build.version.sdk"), adb.shell("getprop", "ro.product.cpu.abilist")))

    before = adb.packages()
    say("Installing " + os.path.basename(args.apk) + " ...")
    code, text = adb.run("install", "-r", "-t", args.apk, timeout=600)
    if "Success" not in text:
        tail = "\n".join(text.strip().splitlines()[-4:])
        say("ERROR: the APK did not install.\n" + tail)
        if "NO_MATCHING_ABIS" in text:
            say("This device cannot run the APK's CPU type. For the GitHub virtual phone, rebuild with 'Also build x86_64' ticked.")
        if "UPDATE_INCOMPATIBLE" in text or "signatures do not match" in text:
            say("An older copy signed with a different key is installed. Uninstall it from the device and test again.")
        return finish("ERROR", 2)
    after = adb.packages()
    package = args.package
    if not package:
        new = sorted(after - before)
        match = sorted(p for p in after if p.startswith(args.prefix))
        package = new[0] if len(new) == 1 else (match[0] if len(match) >= 1 else (new[0] if new else None))
    if not package:
        say("ERROR: installed, but the app's package id could not be worked out. Re-run with --package <id>.")
        return finish("ERROR", 2)
    say("Package: " + package)

    for name in CRASH_FILES + EXTRA_FILES:
        adb.run("shell", "run-as", package, "rm", "-f", name)
    adb.run("logcat", "-c")
    adb.shell("am", "force-stop", package)
    code, text = adb.run("shell", "monkey", "-p", package, "-c", "android.intent.category.LAUNCHER", "1", timeout=60)
    if "No activities found" in text or "monkey aborted" in text.lower():
        say("ERROR: the app has no launchable screen.\n" + text.strip()[-300:])
        return finish("ERROR", 2)
    say("Launched. Watching it for %d seconds ..." % args.seconds)

    started = time.time()
    first_pid = None
    died = None
    reason = ""
    while time.time() - started < args.seconds:
        time.sleep(1)
        elapsed = time.time() - started
        parts = adb.shell("pidof", package, timeout=20).split()
        pid = parts[0] if parts and parts[0].isdigit() else None
        if pid and first_pid is None:
            first_pid = pid
        elif first_pid and pid != first_pid:
            died = elapsed
            reason = "the app closed" if pid is None else "the app crashed and Android restarted it"
            break
        elif first_pid is None and elapsed > 20:
            died = elapsed
            reason = "the app never started"
            break

    code, shot = adb.run("exec-out", "screencap", "-p", binary=True, timeout=30)
    if shot[:4] == b"\x89PNG":
        with open(os.path.join(out, "screenshot.png"), "wb") as handle:
            handle.write(shot)
    code, logtext = adb.run("logcat", "-d", "-v", "time", timeout=120)
    with open(os.path.join(out, "logcat.txt"), "w", encoding="utf-8", errors="replace") as handle:
        handle.write(logtext)
    lines = logtext.splitlines()
    interesting = [l for l in lines if re.search(r"[A-Z]/(python|SDL|SDLActivity|AndroidRuntime|DEBUG)\b", l)
                   or "Fatal signal" in l or (package in l and ("died" in l or "Force finishing" in l))]
    with open(os.path.join(out, "python_log.txt"), "w", encoding="utf-8", errors="replace") as handle:
        handle.write("\n".join(interesting) + "\n")
    crash_text = ""
    for name in CRASH_FILES + EXTRA_FILES:
        code, content = adb.run("shell", "run-as", package, "cat", name)
        if code != 0 or not content.strip() or "No such file" in content or "run-as:" in content:
            continue
        with open(os.path.join(out, os.path.basename(name)), "w", encoding="utf-8", errors="replace") as handle:
            handle.write(content)
        if name in CRASH_FILES:
            crash_text += content + "\n"

    start = None
    for index, line in enumerate(interesting):
        if "Traceback (most recent call last)" in line:
            start = index
    detail = [strip_prefix(x) for x in interesting[start:start + 45]] if start is not None else []
    if not detail and crash_text:
        detail = crash_text.strip().splitlines()[-40:]
    if not detail:
        for index, line in enumerate(lines):
            if "FATAL EXCEPTION" in line or "Fatal signal" in line:
                detail = [strip_prefix(x) for x in lines[index:index + 16]]
                break

    crashed = died is not None or bool(crash_text)
    if crashed:
        say("RESULT: CRASH - " + (reason or "the game reported an error") + (" after %.0f seconds." % died if died is not None else "."))
        if detail:
            say("What the log says:\n  " + "\n  ".join(detail))
        else:
            say("No traceback was found; open logcat.txt in the results folder and search for 'python' or 'FATAL'.")
        return finish("CRASH", 1)
    say("RESULT: PASS - the app was still running after %d seconds." % args.seconds)
    say("A screenshot and the full log are in the results folder.")
    return finish("PASS", 0)


if __name__ == "__main__":
    sys.exit(main())
